do $$ begin create type public.analise_status as enum ('analisado','visitei','comprei','vendi'); exception when duplicate_object then null; end $$;
create table if not exists public.analises(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,titulo_anuncio text not null,preco_anunciado numeric(12,2) not null check(preco_anunciado>=0),categoria text,link_anuncio text,texto_anuncio text not null default '',analise_ia jsonb not null default '{}'::jsonb,margem_lucro_potencial numeric(10,2),oferta_recomendada numeric(12,2) check(oferta_recomendada is null or oferta_recomendada>=0),status public.analise_status not null default 'analisado',preco_compra_real numeric(12,2),preco_venda_real numeric(12,2),lucro_realizado numeric(12,2) generated always as(case when preco_compra_real is not null and preco_venda_real is not null then preco_venda_real-preco_compra_real else null end) stored,data_criacao timestamptz not null default now(),data_atualizacao timestamptz not null default now(),constraint analises_tem_fonte check(link_anuncio is not null or length(btrim(texto_anuncio))>0));
create index if not exists analises_user_data_idx on public.analises(user_id,data_criacao desc);create index if not exists analises_user_status_idx on public.analises(user_id,status);
create or replace function public.set_analises_updated_at() returns trigger language plpgsql security invoker set search_path='' as $$ begin new.data_atualizacao=now();return new;end; $$;
drop trigger if exists set_analises_updated_at on public.analises;create trigger set_analises_updated_at before update on public.analises for each row execute function public.set_analises_updated_at();
